void StyleCascade::Apply(CascadeFilter filter) {
  CollectDeclarationsIfNeeded();
  state_.InvalidateLengthConversionData();

  if (has_applied_) {
    map_.ClearAppliedFlags();
  }
  has_applied_ = true;

  // For performance avoid stack initialization on this large object.
  STACK_UNINITIALIZED CascadeResolver resolver(filter);

  ApplyCascadeAffecting(resolver);

  ApplyViewportUnitAffecting(resolver);
  ApplyHighPriority(resolver);
  state_.UpdateFont();

  if (map_.NativeBitset().Has(CSSPropertyID::kLineHeight)) {
    LookupAndApply(GetCSSPropertyLineHeight(), resolver);
  }
  state_.UpdateLineHeight();

  ApplyWideOverlapping(resolver);

  ApplyMatchResult(resolver);
  ApplyInterpolations(resolver);

ResolvedStyle TreeResolver::styleForStyleable(const Styleable& styleable, ResolutionType resolutionType, const ResolutionContext& resolutionContext, const Style::ComputedStyle* existingStyle)
{
    if (resolutionType == ResolutionType::AnimationOnly && styleable.lastStyleChangeEventStyle() && !styleable.hasPropertiesOverridenAfterAnimation())
        return { Style::ComputedStyle::clonePtr(*styleable.lastStyleChangeEventStyle()) };

ResolutionContext TreeResolver::makeResolutionContext()
{
    return {
        .parentStyle = &parent().style,
        .parentBoxStyle = parentBoxStyle(),
        .documentElementStyle = documentElementStyle(),
        .selectorMatchingState = &scope().selectorMatchingState,
        .treeResolutionState = &m_treeResolutionState
    };
}

    auto previousLastStyleChangeEventStyle = styleable.lastStyleChangeEventStyle() ? Style::ComputedStyle::clonePtr(*styleable.lastStyleChangeEventStyle()) : nullptr;
    // Record the style prior to applying animations for this style change event.
    styleable.setLastStyleChangeEventStyle(Style::ComputedStyle::clonePtr(*resolvedStyle.style));

    // Apply all keyframe effects to the new style.
    HashSet<AnimatableCSSProperty> animatedProperties;
    auto animatedStyle = Style::ComputedStyle::clonePtr(*resolvedStyle.style);

    auto animationImpact = styleable.applyKeyframeEffects(*animatedStyle, animatedProperties, previousLastStyleChangeEventStyle.get(), resolutionContext);

    if (*resolvedStyle.style == *animatedStyle && animationImpact.isEmpty() && previousLastStyleChangeEventStyle)
        return { WTF::move(resolvedStyle.style), animationImpact };

    if (resolvedStyle.matchResult) {
        auto animatedStyleBeforeCascadeApplication = Style::ComputedStyle::clonePtr(*animatedStyle);
        // The cascade may override animated properties and have dependencies to them.
        auto overriddenAnimatedProperties = applyCascadeAfterAnimation(*animatedStyle, animatedPropertySources(styleable, animatedProperties), *resolvedStyle.matchResult, element, resolutionContext);
        ASSERT(styleable.keyframeEffectStack());
        styleable.keyframeEffectStack()->cascadeDidOverrideProperties(overriddenAnimatedProperties, document);
        styleable.setHasPropertiesOverridenAfterAnimation(!overriddenAnimatedProperties.isEmpty());
    }

    Adjuster adjuster(document, *resolutionContext.parentStyle, resolutionContext.parentBoxStyle, !styleable.pseudoElementIdentifier ? &styleable.element : nullptr);
    adjuster.adjustAnimatedStyle(*animatedStyle, animationImpact);

    return { WTF::move(animatedStyle), animationImpact };
};

if (currentStyle && parent().needsUpdateQueryContainerDependentStyle)
    styleable.queryContainerDidChange();

// First, update CSS Transitions and timelines (skipped when printing or in back/forward cache).
updateTransitionsAndTimelines();

// CSS Animations must be updated even during printing to reflect the current animation state.
// FIXME: CSS Transitions and scroll/view-driven animations may also need to be updated during printing.
// The order in which CSS Transitions and CSS Animations are updated matters since CSS Transitions define the after-change style
// to use CSS Animations as defined in the previous style change event. As such, we update CSS Animations after CSS Transitions
// such that when CSS Transitions are updated the CSS Animations data is the same as during the previous style change event.
if (document->backForwardCacheState() == Document::NotInBackForwardCache && !skipAnimationForAnchorPosition) {
    if ((oldStyle && !oldStyle->animations().isInitial()) || !resolvedStyle.style->animations().isInitial())
        styleable.updateCSSAnimations(oldStyle, *resolvedStyle.style, resolutionContext, newStyleOriginatedAnimations, isInDisplayNoneTree);
}

// Now we can update all Web animations, which will include CSS Animations as well
// as animations created via the JS API.
auto [newStyle, animationImpact] = applyAnimations();

HashSet<AnimatableCSSProperty> TreeResolver::applyCascadeAfterAnimation(Style::ComputedStyle& animatedStyle, const HashMap<AnimatableCSSProperty, EnumSet<PropertyCascade::AnimationSource>>& animatedProperties, const MatchResult& matchResult, const Element& element, const ResolutionContext& resolutionContext)
{
    auto builderContext = BuilderContext {
        .document = m_document.get(),
        .parentStyle = resolutionContext.parentStyle,
        .parentHighlightStyle = resolutionContext.parentHighlightStyle,
        .rootElementStyle = resolutionContext.documentElementStyle,
        .element = &element,
        .treeResolutionState = &m_treeResolutionState
    };

    auto styleBuilder = Builder {
        animatedStyle,
        WTF::move(builderContext),
        matchResult,
        { PropertyCascade::PropertyType::AfterAnimation },
        &animatedProperties
    };

    styleBuilder.applyAllProperties();

    return styleBuilder.overriddenAnimatedProperties();
}

void Styleable::updateCSSAnimations(const Style::ComputedStyle* currentStyle, const Style::ComputedStyle& newStyle, const Style::ResolutionContext& resolutionContext, WeakStyleOriginatedAnimations& newStyleOriginatedAnimations, Style::IsInDisplayNoneTree isInDisplayNoneTree) const
{
    auto& keyframeEffectStack = ensureKeyframeEffectStack();

    // Cancel all animations and disregard new ones when this element is newly getting
    // "display: none", or when it is in a display:none subtree due to an ancestor (so
    // that animations restart when the subtree becomes visible again).
    if (((!currentStyle || currentStyle->display() != Style::DisplayType::None) && newStyle.display() == Style::DisplayType::None)
        || isInDisplayNoneTree == Style::IsInDisplayNoneTree::Yes) {
        for (auto& cssAnimation : animationsCreatedByMarkup())
            cssAnimation->cancelFromStyle();
        keyframeEffectStack.setCSSAnimationList(std::nullopt);
        setAnimationsCreatedByMarkup({ });
        return;
    }

    auto& currentAnimationList = newStyle.animations();
    auto& previousAnimationList = keyframeEffectStack.cssAnimationList();
    if (!element.hasPendingKeyframesUpdate(pseudoElementIdentifier) && previousAnimationList && !previousAnimationList->isInitial() && !newStyle.animations().isInitial() && *previousAnimationList == newStyle.animations() && !animationListContainsNewlyValidAnimation(newStyle.animations()))
        return;

bool foundMatchingAnimation = false;
for (auto& previousAnimation : previousAnimations) {
    if (previousAnimation->animationName() == currentAnimationName) {
        // Timing properties or play state may have changed so we need to update the backing animation with
        // the Animation found in the current style.
        previousAnimation->setBackingStyleAnimation(currentAnimation, newStyle.usedZoomForLength());
        // Keyframes may have been cleared if the @keyframes rules was changed since
        // the last style update, so we must ensure keyframes are picked up.
        previousAnimation->updateKeyframesIfNeeded(currentStyle, newStyle, resolutionContext);
        newStyleOriginatedAnimations.append(previousAnimation.ptr());
        newAnimations.add(previousAnimation);
        // Remove the matched animation from the list of previous animations so we may not match it again.
        previousAnimations.remove(previousAnimation);
        foundMatchingAnimation = true;
        break;
    }
}

if (!foundMatchingAnimation && isInDisplayNoneTree == Style::IsInDisplayNoneTree::No) {
    auto cssAnimation = CSSAnimation::create(*this, Style::Animation { currentAnimation }, newStyle.usedZoomForLength(), currentStyle, newStyle, resolutionContext);
    newStyleOriginatedAnimations.append(cssAnimation.ptr());

if (!m_overriddenProperties.contains(Property::Delay))
    animationEffect->setDelay(Seconds(animation.delay().value));

if (!m_overriddenProperties.contains(Property::Duration)) {
    WTF::switchOn(animation.duration(),
        [&](const CSS::Keyword::Auto&) {
            animationEffect->setIterationDuration(std::nullopt);
        },
        [&](const Style::SingleAnimationDuration::Time& time) {
            animationEffect->setIterationDuration(Seconds(time.value));
        }
    );
}

// If we have applied this property for some reason already we must apply anything that overrides it.
if (mayOverrideExistingProperty(propertyID, *current.value()))
    return true;

if (m_includedProperties.types.contains(PropertyType::AfterAnimation)) {
    if (shouldApplyAfterAnimation(current)) {
        m_animationLayer->overriddenProperties.add(propertyID);
        return true;
    }
    return false;
}

bool PropertyCascade::shouldApplyAfterAnimation(const StyleProperties::PropertyReference& property)
{
    ASSERT(m_animationLayer);

    auto id = property.id();
    RefPtr customProperty = dynamicDowncast<CSSCustomPropertyValue>(*property.value());

    auto animationSource = m_animationLayer->properties.getOptional(customProperty ? AnimatableCSSProperty { customProperty->name() } : id);
    if (animationSource) {
        // "Important declarations from all origins take precedence over animations."
        // https://drafts.csswg.org/css-cascade-5/#importance
        // But transitions take precedence over !important, so only allow the
        // override for properties not animated by a transition.
        return !animationSource->contains(AnimationSource::CSSTransition) && property.isImportant();
    }

    // If we are animating custom properties they may affect other properties so we need to re-resolve them.
    if (m_animationLayer->hasCustomProperties) {
        // We could check if the we are actually animating the referenced variable. Indirect cases would need to be taken into account.
        if (customProperty && customProperty->isVariableReference())
            return true;
        if (property.value()->hasSubstitutionFunctions())
            return true;
    }

    // Check for 'em' units and similar property dependencies.
    if (m_animationLayer->hasFontSize || m_animationLayer->hasLineHeight) {
        auto dependencies = protect(property.value())->computedStyleDependencies();
        if (m_animationLayer->hasFontSize && dependencies.properties.contains(CSSPropertyID::FontSize))
            return true;
        if (m_animationLayer->hasLineHeight && dependencies.properties.contains(CSSPropertyID::LineHeight))
            return true;
    }

    return false;
}

void Builder::applyAllProperties()
{
    if (m_cascade.isEmpty())
        return;

    applyTopPriorityProperties();
    applyHighPriorityProperties();
    applyNonHighPriorityProperties();

    adjustAfterApplying();

// High priority properties may affect resolution of other properties (they are mostly font related).
void Builder::applyHighPriorityProperties()
{
    if (m_cascade.applyLowPriorityOnly())
        return;

    applyProperties(firstHighPriorityProperty, lastHighPriorityProperty);
    m_state->updateFont();
    // This needs to apply before other properties for the `lh` unit, but after updating the font.
    applyProperties(CSSPropertyID::LineHeight, CSSPropertyID::LineHeight);
}

void Builder::applyNonHighPriorityProperties()
{
    ASSERT(!m_state->fontDirty());

    applyProperties(firstLowPriorityProperty, lastLowPriorityProperty);
    applyLogicalGroupProperties();
    // Any referenced custom properties are already resolved. This will resolve the remaining ones.
    applyCustomProperties();

template<CSS::NumericRaw RawType> struct ToStyle<CSS::UnevaluatedCalc<RawType>> {
    using From = CSS::UnevaluatedCalc<RawType>;
    using To = typename ToStyleMapping<typename RawToCSSMapping<RawType>::type>::type;

    template<typename... Rest> auto operator()(const From& value, Rest&&... rest) -> To
    {
        return { canonicalize(RawType { To::unit, value.evaluate(rest...) }, rest...) };
    }
};

template<CSS::Numeric NumericType> struct ToStyle<NumericType> {
    using From = NumericType;
    using To = typename ToStyleMapping<From>::type;

    template<typename... Rest> auto operator()(const From& value, Rest&&... rest) -> To
    {
        return WTF::switchOn(value, [&](const auto& value) -> To { return toStyle(value, std::forward<Rest>(rest)...); });
    }

void ComputedStyleDependenciesCollector<LengthUnit>::operator()(ComputedStyleDependencies& dependencies, LengthUnit lengthUnit)
{
    using enum LengthUnit;

    switch (lengthUnit) {
    case Rcap:
    case Rch:
    case Rex:
    case Ric:
    case Rem:
        dependencies.rootProperties.appendIfNotContains(CSSPropertyID::FontSize);
        break;
    case Rlh:
        dependencies.rootProperties.appendIfNotContains(CSSPropertyID::FontSize);
        dependencies.rootProperties.appendIfNotContains(CSSPropertyID::LineHeight);
        break;
    case Em:
    case QuirkyEm:
    case Ex:
    case Cap:
    case Ch:
    case Ic:
        dependencies.properties.appendIfNotContains(CSSPropertyID::FontSize);
        break;
    case Lh:
        dependencies.properties.appendIfNotContains(CSSPropertyID::FontSize);
        dependencies.properties.appendIfNotContains(CSSPropertyID::LineHeight);
        break;

void CSSAnimation::setBackingStyleAnimation(const Style::Animation& backingStyleAnimation, Style::ZoomFactor backingStyleZoomForLength)
{
    m_backingStyleAnimation = backingStyleAnimation;
    m_backingStyleZoomForLength = backingStyleZoomForLength;
    syncPropertiesWithBackingAnimation();
}
